"""Versioned platform instructions. No invented company policies or employee data."""
DOCUMENTS=[
('Возможности JanaМен и помощь помощника','JanaМен объединяет профиль сотрудника, заявки на отпуск, Workspace, Academy, календарь, сервисные обращения, адаптацию и уведомления. Jana помогает найти инструкцию, объяснить действия в интерфейсе и проверить доступные сведения своего аккаунта. Помощник ведёт обычный диалог, помогает с платформой и общими рабочими вопросами. Не принимает кадровые решения и не раскрывает закрытые записи коллег. Конкретные кадровые правила уточняйте у HR.','платформа,janamen,janaмен,возможности,помощь,умеешь,работает,platform,help,платформада'),
('Workspace: пространства, задачи и комментарии','Откройте Workspace. Нажмите «Новое пространство», задайте название и выберите участников. В общем пространстве задачи и документы доступны его участникам. Создатель пространства управляет составом. Для задачи нажмите «Новая задача», укажите название, описание, исполнителя, срок и приоритет. Откройте карточку для смены статуса и добавления комментария. Статусы: «К выполнению», «В работе», «Готово». Изменения появляются в активных кабинетах после опроса сервера примерно раз в три секунды. Одновременного редактирования текста документа нет. Личные заметки доступны только своему автору.','workspace,воркспейс,пространств,задач,канбан,комментар,заметк,task,space,notes,тапсырма,міндет,вазифа,даалгавар,даалгавар,тэмдэглэл'),
('Документы: загрузка, передача и поиск','В Workspace в блоке «Документы» нажмите «Загрузить». Выберите файл, пространство или разрешённых получателей. Максимальный размер файла — 2 МБ, общий лимит владельца — 30 МБ. Поиск работает по названию и извлечённому содержимому TXT, MD, CSV и DOCX. Для содержимого PDF нужна необязательная библиотека pypdf; без неё PDF ищется по имени. Сканированные PDF и изображения не распознаются OCR. Скачивание разрешено владельцу и пользователям с предоставленным доступом. Удалить файл может владелец.','файл,документ,загруз,скача,переда,поиск,file,upload,download,search,құжат,іздеу,ҳуҷҷат,hujjat,fayl,баримт,документ'),
('Сервисы: обращения в HR, IT и офис','Откройте «Сервисы» и нажмите «Новое обращение». Выберите HR, IT или офис, заполните тему и описание. HR выполняет диспетчеризацию и назначает ответственного. В карточке обращения доступны статус и комментарии. Создание обращения регистрирует запрос, но само по себе не создаёт почтовый ящик и не выдаёт оборудование. Срок выполнения уточняйте у ответственного; фиксированного SLA в системе не задано.','сервис,обращен,поддержк,почт,оборудован,it,офис,ticket,support,service,өтініш,қолдау,көмек,дастгирӣ,хизмат,жабдуу'),
('Адаптация: маршрут нового сотрудника','HR назначает сотруднику маршрут адаптации из четырёх шагов и срок. Сотрудник открывает «Адаптация», проверяет свои шаги и отмечает выполненные действия. Учебный шаг закрывается по результату прохождения назначенного курса в Academy, а не ручной отметкой. Процент показывает долю завершённых шагов.','адаптац,маршрут,нович,первый день,onboarding,бейімдел,мутобиқ,дасан зохиц,көнүү'),
('Календарь команды и отсутствия','В разделе «Календарь» выберите месяц. Видны только заявки, доступные вашей роли. Заявка на согласовании обозначает предварительное отсутствие, а не утверждённый график. Блок пересечений показывает совпадения периодов разных сотрудников среди доступных заявок выбранного месяца. Календарь не раскрывает закрытые заявки чужой команды.','календар,пересеч,отсутств,calendar,absence,күнтізбе,тақвим,тақвим,хуанли'),
('Вход, временный пароль и восстановление доступа','Публичной регистрации нет: аккаунт создаёт HR в разделе «Управление». При создании или сбросе HR выдаёт временный пароль; при следующем входе сотрудник обязан сменить его. Если пароль забыт, обратитесь в HR: восстановление через email не подключено. HR может блокировать доступ. Не передавайте пароль, API-ключ или файл настроек другим сотрудникам.','вход,парол,регистрац,аккаунт,сброс,восстанов,login,password,account,кіру,құпиясөз,парол,нэвтрэх'),
('AI Jana: подключение и границы ответа','Jana ведёт обычный диалог с подключённой моделью, в том числе напрямую через Google Gemini API. В API передаются сообщения текущего чата и доступные роли инструкции как справочный контекст. Отсутствие статьи не блокирует ответ; обязательных цитат нет. При ошибке API показана ошибка, а не готовая выдержка. Запросы о своих заявках, задачах, курсах и профиле обрабатываются локально без передачи кадровых записей. Точное название модели задаётся в настройках сервера. Не отправляйте в чат пароли, ключи и персональные данные. Помощник не подписывает документы и не принимает кадровые решения.','ии,ai,модель,чат,источник,цитат,anymodel,groq,помощник,assistant,бот,сөйлесу'),
('Мобильный доступ и работа без интернета','Для телефона платформа открывается по общему HTTPS-адресу сервера и может устанавливаться как PWA. Сервер на ноутбуке должен работать, пока им пользуются. Без соединения заявки и изменения не отправляются; старые кадровые статусы не выдаются за актуальные. PWA не является отдельным нативным приложением и не доставляет фоновые push-уведомления.','телефон,мобильн,pwa,интернет,офлайн,установ,mobile,offline,phone,утас,оффлайн'),
('HR: управление аккаунтами, базой знаний и курсами','Раздел «Управление» доступен HR. HR создаёт аккаунты, сбрасывает пароли, блокирует доступ и редактирует кадровые поля. Источники базы знаний имеют аудиторию и версию; публикуйте только проверенные инструкции. HR создаёт курсы в визуальном редакторе и назначает их сотрудникам. Назначенный курс защищён от изменения: создайте новую версию.','hr,управлен,созда,аккаунт,курс,база,источник,administration,admin','hr'),
]
UI_DOCUMENTS=[
('Оформление: тема и цвет фона','В верхней панели JanaМен есть кнопка со значком солнца для смены темы. На компьютере рядом указано название текущего режима: «Системная», «Светлая» или «Тёмная». Нажимайте кнопку: режимы переключаются по кругу «Системная» → «Светлая» → «Тёмная» → «Системная». В системном режиме оформление следует настройке устройства. На телефоне кнопка находится в верхней полосе над логотипом. Выбранная тема сохраняется в этом браузере. Произвольный цвет фона или собственная цветовая палитра в интерфейсе не предусмотрены: доступны светлая и тёмная темы, а также системный режим.','фон,тема,темн,тёмн,светл,цвет,оформлен,theme,background,dark,light,түс'),
]
def _add_documents(db,documents,marker):
 if db.execute('SELECT 1 FROM schema_changes WHERE name=?',(marker,)).fetchone():return
 for row in documents:
  title,body,keywords=row[:3];audience=row[3] if len(row)>3 else 'all'
  if not db.execute('SELECT 1 FROM knowledge WHERE title=?',(title,)).fetchone():db.execute('INSERT INTO knowledge(title,body,keywords,audience) VALUES(?,?,?,?)',(title,body,keywords,audience))
 db.execute('INSERT INTO schema_changes VALUES(?)',(marker,));db.commit()
def initialize(db):
 _add_documents(db,DOCUMENTS,'ai-knowledge-v2')
 _add_documents(db,UI_DOCUMENTS,'ai-ui-knowledge-v1')
 _migrate_chat_instructions(db)


def _migrate_chat_instructions(db):
 db.execute('UPDATE knowledge SET body=?,version=version+1 WHERE title=? AND body=?',('JanaМен объединяет профиль сотрудника, заявки на отпуск, Workspace, Academy, календарь, сервисные обращения, адаптацию и уведомления. Jana помогает найти инструкцию, объяснить действия в интерфейсе и проверить доступные сведения своего аккаунта. Помощник ведёт обычный диалог, помогает с платформой и общими рабочими вопросами. Не принимает кадровые решения и не раскрывает закрытые записи коллег. Конкретные кадровые правила уточняйте у HR.','Возможности JanaМен и помощь помощника','JanaМен объединяет профиль сотрудника, заявки на отпуск, Workspace, Academy, календарь, сервисные обращения, адаптацию и уведомления. Jana помогает найти инструкцию, объяснить действия в интерфейсе и проверить доступные сведения своего аккаунта. Помощник не выполняет кадровые решения, не раскрывает закрытые данные коллег и не отвечает на посторонние темы. Если подтверждённого источника нет, обратитесь в HR.'))
 db.execute('UPDATE knowledge SET body=?,version=version+1 WHERE title=? AND body=?',('Jana ведёт обычный диалог с подключённой моделью, в том числе напрямую через Google Gemini API. В API передаются сообщения текущего чата и доступные роли инструкции как справочный контекст. Отсутствие статьи не блокирует ответ; обязательных цитат нет. При ошибке API показана ошибка, а не готовая выдержка. Запросы о своих заявках, задачах, курсах и профиле обрабатываются локально без передачи кадровых записей. Точное название модели задаётся в настройках сервера. Не отправляйте в чат пароли, ключи и персональные данные. Помощник не подписывает документы и не принимает кадровые решения.','AI Jana: подключение и границы ответа','Jana отвечает по разрешённой базе знаний с источниками. При включённом AnyModel или Groq вопрос и найденные инструкции передаются внешней модели; кадровые записи для локальных ответов не передаются. Свои заявки и остаток отпуска можно проверить локально. При сбое провайдера, лимите, тайм-ауте или невалидной цитате показывается выдержка из базы с объяснением причины. Успешный ответ модели не заменяет проверку важной информации в источнике. Помощник не подписывает документы и не принимает кадровые решения.'))
 db.execute("UPDATE knowledge SET body=replace(body,?,?),version=version+1 WHERE title=? AND body LIKE ?",('Jana ведёт обычный диалог с подключённой моделью через AnyModel или Groq.','Jana ведёт обычный диалог с подключённой моделью, в том числе напрямую через Google Gemini API.','AI Jana: подключение и границы ответа','Jana ведёт обычный диалог с подключённой моделью через AnyModel или Groq.%'))
 db.commit()
